import json


def append_workspace_guide(doc, root, add_table, add_code_block, add_figure):
    report = json.loads((root / 'reports/workspace_validation.json').read_text(encoding='utf-8'))
    doc.add_page_break()
    doc.add_heading('Разбиение по предложениям и интерфейс проверки системы', level=1)
    doc.add_paragraph('Обновление от 18 ноября 2026. Разбиение статей теперь собирает чанки из целых предложений и переносит контекст между соседними фрагментами целыми предложениями. Добавлен браузерный интерфейс на корневом адресе API. Через него можно проверить ответ, агента, поиск, классификатор, предпросмотр и реальные чанки индекса. Локальные модели подключены и проверены через этот интерфейс. Экспертная банковская оценка остаётся отдельной незавершённой задачей.')
    doc.add_heading('Почему изменено разбиение', level=2)
    doc.add_paragraph('Прежний алгоритм ограничивал число символов и искал ближайший пробел. Он мог разорвать предложение, а перекрытие по символам иногда начиналось с середины слова. Для ответа цитатой это неудобно: найденный фрагмент может содержать условие без продолжения. Новый алгоритм сначала выделяет предложения, затем собирает последовательные предложения до лимита. Ожидаемая польза — более связный контекст; улучшение банковских метрик пока не измерено.')
    doc.add_paragraph('Используется pySBD 0.3.4: небольшой rule-based сегментатор, который не требует загрузки языковой модели. Для русского и английского проверены обычная пунктуация, десятичное число, английское сокращение Dr. и URL. Это набор регрессионных примеров, а не доказательство правильной сегментации любого банковского документа. Таблицы, списки, неоднозначные сокращения и смешанные языки могут потребовать отдельных правил и проверки на реальных статьях. clean=False сохраняет содержимое; перед сегментацией пробельные последовательности нормализуются.')
    add_code_block(doc, '''{
  "strategy": "sentences_pysbd034_v1",
  "max_chars": 900,
  "overlap_sentences": 1
}''')
    doc.add_heading('Алгоритм и случаи превышения лимита', level=2)
    doc.add_paragraph('Предложения добавляются в текущий чанк последовательно, с пробелом между ними. Если следующее предложение превышает общий лимит, текущий чанк сохраняется. Из его конца берётся до overlap_sentences целых предложений. Если перекрытие вместе с новым предложением не помещается, самые ранние предложения перекрытия удаляются. Перекрытие поэтому может быть меньше заданного; лимит и продвижение по тексту сохраняются.')
    add_code_block(doc, '''Исходный текст
First sentence here. Second sentence here. Third sentence here.

max_chars = 43, overlap_sentences = 1

Чанк 1
First sentence here. Second sentence here.

Чанк 2
Second sentence here. Third sentence here.''')
    doc.add_paragraph('Если одно предложение длиннее max_chars, оно разбивается по словам без перекрытия фрагментов. Слово, которое само длиннее лимита, разрезается по символам. Это явный fallback: интерфейс сообщает число слишком длинных предложений. Такие части не используются как полные предложения перекрытия. Отдельные тесты проверяют ограничение размера, сохранение непробельных символов, последний фрагмент и отсутствие бесконечного цикла при большом overlap.')
    doc.add_heading('Совместимость конфигураций и калибровки', level=2)
    doc.add_paragraph('Старые конфигурации с overlap_chars и без strategy интерпретируются как characters_v1. Они продолжают использовать прежний алгоритм. Новые настройки явно содержат sentences_pysbd034_v1 и overlap_sentences; смешивание этих параметров отклоняется. Это предотвращает незаметное изменение смысла старого файла конфигурации. Текущие configs/retrieval.json и демонстрационный runner переведены на предложения.')
    doc.add_paragraph('API сравнивает нормализованные параметры активного индекса и calibration manifest. Если индекс строится по предложениям, а порог относится к символьному разбиению, порог отключается с calibration_mismatch. В хеши демонстрационного запуска добавлен src/rag/chunking.py. Для банковского runner дополнительно фиксируются файл сегментатора и версия pysbd. Старые кандидаты после изменения реализации требуют новой calibration; их holdout повторно не открывался.')
    doc.add_paragraph('Демонстрационный набор уже использовался для разработки, поэтому пересчёт его порогов и regression оценки после изменения chunking не является новой независимой проверкой качества. На 16 коротких статьях при первой проверке интерфейса получилось 16 чанков: тексты помещаются в лимит 900. Само число чанков поэтому не обязано измениться. Разницу удобнее изучить на длинном тексте во вкладке «Чанки» с меньшим лимитом.')
    doc.add_paragraph('Сохранённый reports/public_banking_probe.json помечен historical_before_sentence_chunking и содержит прежние параметры characters_v1. Его значения нельзя считать оценкой нового алгоритма. Отдельная пометка добавлена в ноутбук 09. Исследовательский банковский корпус не подключался к обслуживанию и не получил автоматического экспертного одобрения.')
    doc.add_heading('Архитектура интерфейса', level=2)
    doc.add_paragraph('Фронтенд находится в frontend/index.html, styles.css и app.js. Это самостоятельные HTML, CSS и JavaScript без сборки npm. Для небольшого набора диагностических сценариев такой вариант уменьшает число зависимостей и позволяет проследить полный запрос. FastAPI отдаёт страницу на / и статические файлы на /assets. Запросы идут на тот же origin, поэтому отдельный frontend сервер и настройка CORS не требуются. Dockerfile копирует frontend в образ.')
    add_table(doc, ['Режим', 'Что показывает', 'Основной endpoint'], [
        ('Ответ по базе', 'Текст, источники, отказ и понятная причина', 'POST /v1/knowledge/answer'),
        ('Агент', 'Ответ или уточнение, черновик передачи и trace шагов', 'POST /v1/agent/run'),
        ('Поиск', 'Найденные фрагменты, score и порог', 'POST /v1/knowledge/search'),
        ('Классификация', 'Одна из 77 английских банковских категорий', 'POST /v1/classify'),
        ('Чанки', 'Разбиение своего текста без изменения индекса', 'POST /v1/chunks/preview')])
    doc.add_paragraph('Кнопка «Посмотреть базу» открывает каталог статей. Выбор статьи показывает реальные фрагменты уже загруженного индекса, а не реконструированный текст из перекрывающихся частей. Метаданные и фрагменты возвращают GET /v1/knowledge/documents и GET /v1/knowledge/chunks. Эти endpoints и предпросмотр находятся под существующей защитой /v1. Предпросмотр ограничен 20 тысячами символов, остальные запросы — двумя тысячами. Классификация явно выделена как английская задача.')
    doc.add_heading('Состояние сервисов и обработка ошибок', level=2)
    doc.add_paragraph('GET /v1/system/status возвращает количество статей и чанков, метод, параметры chunking, готовность классификатора, состояние порогов и наличие настроек локальных моделей. Значения API key не возвращаются. Наличие имени модели означает конфигурацию, а не успешную связь с Ollama; проверка происходит при реальном обращении. Интерфейс заранее объясняет отсутствие базы, порога или модели вместо ожидания, что пользователь разберётся по одному коду 503.')
    doc.add_paragraph('Отказ abstained с HTTP 200 отображается как отдельный результат, а не как пустая карточка. Для 401 предлагается ввести ключ, для 429 — повторить позже, для 503 режима Ollama — проверить модель или использовать extractive. Полный JSON доступен в раскрывающемся блоке. Во время запроса кнопки основных действий блокируются, показывается индикатор и измеряется клиентское время. Отмена прекращает ожидание браузера; сервер может ещё завершать обработку, что прямо указано пользователю.')
    doc.add_heading('Защита данных в браузере', level=2)
    doc.add_paragraph('Ключ вводится через диалог и хранится только в памяти текущей страницы. Он передаётся в x-api-key, не помещается в URL, localStorage или sessionStorage. Кнопка очистки удаляет значение из состояния. Тексты результата создаются через textContent и DOM элементы: HTML из статьи или пользовательского текста не исполняется. В браузере проверено буквальное отображение строки с img и onerror. Ссылки разрешены только для http/https, открываются с noopener noreferrer. На странице задан CSP без inline scripts и обработчиков.')
    doc.add_paragraph('При запуске модели автоматическая проверка отклонила подключение всего work/ollama, поскольку там находится приватный ключ. Для проверки подключён только каталог models, read-only; ключ остался вне контейнера. Compose конфигурация также ограничена подкаталогом моделей, с возможностью загрузки весов через штатный Ollama. Это пример уменьшения области доступа вместо обхода проверки.')
    doc.add_heading('Фактические проверки через интерфейс', level=2)
    doc.add_paragraph(f"Пройдены {report['automated_tests']} автоматический тест и 13 проверок на отдельном настоящем HTTP сервере: страница, assets, авторизация, параметры индекса, calibration, каталог, чанки, preview, 422, цитируемый ответ, уточнение и контролируемый fallback без planner. CI дополнен проверкой синтаксиса JavaScript и этим HTTP сценарием. Браузерная проверка выполнена отдельно; она не подменяется успешным unit test.")
    if report.get('ci'):
        doc.add_paragraph(f"Фактический GitHub Actions запуск завершился со статусом {report['ci']['conclusion']}: {report['ci']['url']}. Проверены Windows и Linux, синтаксис JavaScript, HTTP сценарии и полный контейнерный стенд с HTTPS и мониторингом. Commit реализации: {report['ci']['head_sha']}.")
    doc.add_paragraph('В браузере проверены ответ с источником, поиск, категория lost_or_stolen_card, каталог статей и реальные чанки, предпросмотр, буквальный HTML текст и мобильная ширина 390 без горизонтального переполнения. Ошибок JavaScript в консоли не наблюдалось. Для Qwen2.5 1.5B получен настоящий результат агента: search_knowledge, затем prepare_answer и цитата из install_ru. Отдельно Qwen2.5 0.5B подготовила поддержанную цитату через режим ollama. Это единичные примеры на знакомых статьях о проекте, а не независимая банковская приёмка.')
    doc.add_paragraph('Клиент показал около 9.38 секунды для примера агента и 15.10 секунды для отдельного Ollama ответа. Эти числа не являются P95 или SLA. Продолжительность шага trace включает выбор инструмента планировщиком и его выполнение: строка «Поиск» длительностью несколько секунд не означает, что сам BM25 индекс ищет столько времени. Точные ответы и trace сохранены в reports/workspace_validation.json.')
    add_figure(doc, root / 'reports/figures/workspace_result.jpg', 'Интерфейс после реального запроса к локальной модели с ответом и источником', width=2.8)
    doc.add_heading('Как запустить и изучить код', level=2)
    add_code_block(doc, '''python -m pip install -r requirements.txt
python scripts/start_demo.py

http://127.0.0.1:8000/''')
    doc.add_paragraph('Сначала проверьте режим «Ответ по базе» с extractive: он не требует LLM. Для агента должен работать Ollama с локальной моделью. В созданном локальном окружении контейнер можно включить командой docker start support-workspace-ollama. При запуске API задайте модели в том же терминале:')
    add_code_block(doc, '''$env:AGENT_MODEL = 'qwen2.5:1.5b'
$env:OLLAMA_MODEL = 'qwen2.5:0.5b'
python scripts/start_demo.py''')
    doc.add_paragraph('Изучение удобно начать с src/rag/chunking.py, затем src/api/workspace.py и frontend/app.js. Далее проверьте tests/test_sentence_chunking.py и изменения calibration manifest в src/api/main.py. Для воспроизведения HTTP сценария выполните python scripts/verify_workspace_http.py. README не изменялся; инструкции текущего этапа находятся здесь.')
    doc.add_heading('Вопросы для собеседования о чанках и интерфейсе', level=2)
    for question, answer in [
        ('Почему предложение является полезной границей чанка', 'Оно чаще сохраняет законченную мысль и удобнее для цитирования. Но смысл может зависеть от предыдущего абзаца, поэтому граница предложения сама по себе не гарантирует релевантность.'),
        ('Почему перекрытие иногда меньше заданного', 'Обязателен лимит размера и добавление нового текста. Если все предложения перекрытия не помещаются вместе с новым, ранние удаляются.'),
        ('Почему нужно повторно калибровать отказ', 'Новый chunking меняет длины и набор кандидатов, а значит score и его распределение. Прежний порог относится к прежнему индексу.'),
        ('Почему HTTP 200 может сопровождаться отсутствием ответа', 'Приложение успешно обработало запрос и приняло решение abstained. Фронтенд должен показать причину отказа, а не трактовать любой 200 как наличие текста.'),
        ('Почему не стоит считать smoke пример агента оценкой качества', 'Он проверяет доступность модели, выбор инструментов и контракт на знакомой задаче. Для качества нужны независимые вопросы, экспертные метки и заранее фиксированные критерии.')]:
        doc.add_paragraph(question, style='Heading 3')
        doc.add_paragraph(answer)
    doc.add_paragraph('Первичные материалы по использованным API: https://github.com/nipunsadvilkar/pySBD и https://fastapi.tiangolo.com/tutorial/static-files/ . Ограничения и фактические проверки этой реализации сохранены в reports/workspace_validation.json.')
    doc.add_heading('Почему на вопрос об АПИ сначала не было ответа', level=2)
    doc.add_paragraph('В режиме «Ответ по базе» пользователь спросил «Что такое АПИ?» и выбрал топ-10. В исходных 16 статьях была команда запуска API. Определение программного интерфейса отсутствовало. Поиск вернул результат ниже порога, поэтому приложение показало причину отказа. Топ-10 задаёт максимальное число кандидатов. При подготовке ответа система отдельно проверяет оценку первого кандидата.')
    doc.add_paragraph('В data/demo/articles.jsonl добавлена статья api_definition_ru с определением и примером обмена между браузером и сервером. В статье встречаются оба написания термина. После пересборки демонстрационного индекса в нём 17 статей и 17 чанков. Скрипт scripts/verify_workspace_http.py проверяет вопросы «Что такое АПИ?» и «Что такое API?» по HTTP с top_k=10 и ищет определение в тексте ответа. Вместе с предыдущими сценариями успешно прошли 15 проверок. Вопросы обо всех остальных темах по-прежнему зависят от содержания базы.')
    doc.add_heading('Как проследить решение агента', level=2)
    doc.add_paragraph('Во вкладке «Агент» задайте вопрос «Как установить зависимости проекта?» и откройте шаги. В проверенном запуске Qwen выбрала search_knowledge, получила результат поиска и затем выбрала prepare_answer. Сервер проверил для каждой цитаты идентификаторы статьи и чанка, источник и вхождение цитаты в текст. В ответ попали выдержки из install_ru. Для сравнения введите «Ничего не работает». Сервер сразу запросит уточнение, а в техническом ответе planner_calls будет равен нулю.')
    doc.add_paragraph('Если для ответа нет подходящей статьи, доступны уточнение и черновик для оператора. В результате handoff поле ticket_draft.submitted равно false. Для английского обращения до поиска доступен также классификатор BANKING77. Допустимые действия после каждого шага вычисляет run_agent в src/agent/service.py. По умолчанию цикл ограничен четырьмя шагами.')
